'use strict';

var fac = require( '@stdlib/plot/unicode/base/lib' );
var opt = {
	'plotAreaHeight': 10,
	'plotAreaWidth': 100,
	// 'axisTicsLabels': [ [1, 10], [ 1, 2 ], [ 5 ], [ 6 ] ],
	'labelFormate': [ '%s', '%s', '%s', '%s' ],
	'ticsSpacing': [ 9, 99, 7, 98],
	'backgroundColor': 'Bwhite',
	'foregroundColor': 'Fblack',
	'autoRender': true,
	'verticalTicsGlyph': 'block',
	'verticalAxisGlyph': 'dot',
	'horizontalTicsGlyph': 'block',
	'horizontalAxisGlyph': 'dot',

	'xAxisPos': 50,

	'yAxisPos': 5,

	// 'autoInitialize': true

	// 'autoRender': true,
	'autoInitialization': true,

	'zAxisPos': 10,

	'wAxisPos': 8
};
var ins = new fac( opt );
ins.initialize();

var pltar = ins.plotArea;

ins.setBackgroundColor( 5, 80, 'Bred', true );
ins.setForegroundColor( 5, 80, 'Fgreen', true );
ins.setGlyph( 5, 80, 'horizontal', true );
ins.setString( 5, 80, "here is my string", true, 'Fred' );
// ins.setBar( [ pltar.y + 1, pltar.x + 1 ], [ pltar.y + 6, pltar.x + 1 ], [ pltar.y + 1, pltar.x + 1 ], [ pltar.y + 6, pltar.x + 1 ], true, 'block' );

// ins.setBar( [ pltar.y + 1, pltar.x + 1 ], [ pltar.y + 6, pltar.x + 1 ], [ pltar.y + 1, pltar.x + 1 ], [ pltar.y + 6, pltar.x + 1 ], true, 'block' );
// ins.setBar( [ pltar.y +1, pltar.x + 3 ], [ pltar.y + 8, pltar.x + 3 ], [ pltar.y + 1, pltar.x + 3 ], [ pltar.y + 8, pltar.x+ 3 ], true, 'block', 'Fred' );

var str = ins.render();
console.log( str );

// console.log('\x1b033[40m');

